@icontract.ensure(lambda a, result: result[0] == a[len(a) - 1])
@icontract.ensure(lambda a, result: result[len(result) - 1] == a[0])
@icontract.ensure(lambda a, result: all(result[i + 1] == a[i + 1] for i in range(len(result) - 2)))
def swapFirstAndLast(a: List[int]) -> List[int]:
